local SCRIPT_CHANGELOG = {
    { version = "6.6.100", date = "2026-09-04", notes = "Chris: there is clearly enough room to fit in the gaps between the mage shots, and he is right. The 2.5 stud misses I padded the shot by were almost certainly along its travel, since it is a moving box thirty five studs long, and padding its width instead closed every gap in a volley: the shots sit about eleven studs apart and seven wide, so the raw gap is under four studs and a pad of 2.5 a side erased it entirely before any margin applied. The pad is gone, the predicted lanes are the shot's own width rather than two wider, and the margin kept from a shot's edge is 1.2 studs on a slider, Mage shot margin, so he can lower it until the middle of the gap turns green and raise it if it takes clips. I cannot see that screen from here; he can." },
    { version = "6.6.99", date = "2026-09-04", notes = "Speed, as Chris asked, with the dials on sliders so he can tune them himself. The escape runs at 24 rather than 22, a burst under danger may hold four seconds rather than two and a half before a half second rest, and the slam alone sprints at 27: two seconds to leave a 67 stud cube is the tightest window in the dungeon and it lasts too briefly to look like anything but a sprint. Both new dials say on the slider what to turn down if a kick follows. Having nowhere to go at all with the ground about to fire now counts as doomed as well, which is what every node refused in a marching volley actually is: the hop answers it instead of the character standing there. And moving for room happens once and then it stands still. Without a wait between moves it went back and forth between two spots that each looked roomier from the other." },
    { version = "6.6.98", date = "2026-09-04", notes = "Two from Chris's screenshots. No safe spot anywhere in a mage volley: slim is meant to cap how much room is kept round a narrow attack, but the lag was added on top of it, and at his ping of 133 ms that is nearly three studs, which pushed every lane back out to the full body margin and closed every gap between them. The lag counts for a third of itself now, and the mage shot keeps 2.5 studs rather than 3.5. Its measured width is unchanged; what changes is the margin drawn round it, which in a volley is the whole difference between gaps and a wall. The passive beam leaving a trace after it fires: a turn of three and a half degrees counted as a fresh cast, so a parked beam drifting round re-opened its window several times a second and stood there permanently live. A re-aim now has to be a real step, and the telegraph has to be lit, which is the game's own signal that it means it." },
    { version = "6.6.97", date = "2026-09-04", notes = "Chris asked whether my changes were reaching his game at all. They were not: I have been staging builds to the Potassium folder on the machine the bridge runs on, and his game is elsewhere, so only the files sent to him ever mattered. From now on the version is written into the recording itself, next to the settings that decide the last resort, so there is no guessing which build produced a file. The sandwich rule is removed entirely. The step check no longer refuses warm ground at all, only lethal, and warm ground while fleeing costs almost nothing. Melee mobs: the soft band past a mob's swing was danger at half strength, which is what made the field keep walking backwards out of the room. It is 0.12 now over four studs rather than 0.5 over ten, the outward part of a strafe step is a stud, and the fallback direction when nothing is chosen is sideways rather than straight away. And the general form of the check the slam has had: every tick, if the ground fires before the legs can reach the spot the field chose, that counts as being inside something lethal - the burst runs and the hop is allowed whatever the clock says. With nothing coming it drifts to the roomiest spot near by rather than standing in a doorway." },
    { version = "6.6.96", date = "2026-09-04", notes = "Low detail actually removes the decoration now. The named models from the stripping script Chris uses went only if nothing inside them was collidable, which for ice shards, dead trees and rubble is never true, so almost none of them ever went. Those names are decoration he has already stripped in this map by hand, so they go whether or not they collide, and the list is longer. What stays out of it is anything you stand on or that keeps you inside the map: the terrain, stairRamps and borders. Deleting those client-side is what forces that script to rebuild the floor out of CFrame parts, and it leaves the character walking where the server still has a wall. It says in the log how many models it removed." },
    { version = "6.6.95", date = "2026-09-04", notes = "The arena of red in Chris's second picture is mine, from the sandwich rule I added yesterday. It counted overlapping BOXES, and Bob's circle line is drawn as three nested bands of the same attack, 0.5, 0.65 and 0.8: the middle of it summed to 1.95 and every point along a four hundred stud strip came back lethal. It counts two different attacks now, the strongest box of each. The mage shot goes back down from slim 4.5 and pad 3.5 to 3.5 and 2.5. At that size a row of shots left no gap between the lanes at all, which is both the wall of red in the first picture and why it walked into one: everything read the same. 2.5 studs is what the misses actually measured. The ice spikes hurt as they rise and then just stand there, so they get one zone for the moment that hurts and a much weaker one for the wall they leave, rather than ten seconds of ground marked dangerous after it is spent. The slam: when the legs cannot reach the edge in the time left, the hop may fire even with the minute's budget spent. The five second floor still stands, because that is the one the kicks follow. And a melee mob is circled rather than retreated from: the outward part of a strafe step is a nudge now, so it stops walking out of the room." },
    { version = "6.6.94", date = "2026-09-04", notes = "The error on line 2852 is the headline, and it explains the last resort. `since`, the time since the last hop, was read inside the mob branch and declared after it: the moment the bot became desperate against a mob it compared nil with a number and threw, the brain caught it and let go of the character, and no hop ever happened in the one situation the hop exists for. It is declared before its use now. Standing inside anything live and lethal also counts as a pickle in its own right whatever the clock says, which is what lets it hop out of a spread beam, a spike circle or a circle hitbox rather than standing there. The Champion's floor is treated as three rings and the bot belongs in the middle-to-outer band rather than the doorway or his lap, costed gently per stud outside it. An escape now prefers open ground over running along a wall. Bob: the pull to the middle of the three crystals is three and a half times what it was, and the keep-away from him drops from 74 studs to 60, which is what was pushing it up the arena. The cost of crossing the span of his wall drops from 22 to 8, and the sandwich rule now needs two boxes of 0.5 rather than 0.35, so a prediction plus a wall lane no longer adds up to lethal ground. And a boss dying clears its attacks whoever it was, read from the enemy list rather than from the one target we happened to be aiming at, with the quiet window at twelve seconds." },
    { version = "6.6.93", date = "2026-09-04", notes = "Seven from Chris. Two warm boxes overlapping are now one lethal box: one is ground worth crossing, but the overlap of two has no step left out of it, which is the sandwich he asked for. The other way round, warm ground is nearly free while running from something lethal, since refusing to cross a warm lane is how the bot ended up in a spike circle: a yellow is not a kill and a red is. The predicted lanes of a mage volley are warm rather than lethal, warmer still the further ahead they are: they are a guess about where a sweep goes next, not a shot that exists, and painting them red is what turned that room solid. The shot that does exist is wider, slim 4.5 and pad 3.5, since hits were still landing where the model called it clear. A spot with a wall inside the padding costs thirty more while dodging, because pinned against a wall is where it dies. The hop against mobs goes to four a minute at six seconds apart rather than two at nine, which is still inside everything that has never drawn a kick. And circling a target with something on the way is a dodge, so it does that at running speed too." },
    { version = "6.6.92", date = "2026-09-04", notes = "Emergency fix for a fault I shipped in 6.6.91. The block that keeps a spot whose straight line is blocked called floorY with a variable that does not exist, so it was handed nil and threw on every candidate: the field stage died sixty times a second and nothing dodged at all. That is the ERROR field :301 on Chris's screen. The floor at that spot has already been found and height-checked a few lines above, so nothing needs looking up again. structcheck now also fails on any identifier used but never declared anywhere in the file, which is exactly what this was." },
    { version = "6.6.91", date = "2026-09-04", notes = "Six from Chris, against a run whose every death still had only two usable nodes out of two hundred and sixteen. Two of these go straight at that. Crossing the span of Bob's wall made a spot as forbidden as the wall itself, and the whole far side of the arena went with it: it costs now, heavily, and anything actually lethal still outranks it four to one. And a spot with something between it and us is no longer thrown away, only costed, since the walk can go round; discarding them is why clean ground behind a rock counted for nothing. The step check that refuses to walk on warm ground also went from 0.6 to 0.92, so only the nearly lethal stops a walk. To answer the question directly: testing each node on its own is what it already does, one raycast for reach plus six short ones for openness, and keeping the blocked ones costs nothing extra. A walk to safety that crosses something lethal now counts as desperate, which is what lets the hop answer it. Extra cast range has a slider for mobs and one for bosses beside the one for everything. And height counts at last: standing on a ledge above a group read as point blank, so it cast at what it could not reach and never walked down. Past heightSplit studs of drop the distance is the real one, through the air." },
    { version = "6.6.90", date = "2026-09-04", notes = "Four from Chris. The oscillation between beams: a new one appearing re-scored every spot and the bot turned round in the middle of the dodge it was already making. A spot that has not gone lethal is now seen through, for dodgeCommit seconds no matter what and after that only for a spot better by dodgeSwitch rather than by a third of a cost unit. The slam's speed burst is never held back now, not even by a foreign walk speed: two seconds to leave a 67 stud cube only just works and nothing may take it away. The mage volley predicts three lanes on rather than one, each graded by when it arrives; predicting only the next one is why the row after it read as clean ground. And the spread beam gets its own escape. It is a line, so the way out is across it rather than away from its middle: the reflex runs from the nearest point on its axis, which makes away mean perpendicular, and it may take a hop on the same budget the slam has." },
    { version = "6.6.89", date = "2026-09-04", notes = "Six from Chris, measured against the run he sent. Eight of its fifteen hits landed with the model saying we were outside everything, which is the whole story of that file. The beams: with a dozen up and their detonations staggered, every spot goes hot eventually and refusing all of them outright leaves nowhere to stand, which is what being overwhelmed looks like. The penalty for a spot that goes hot now falls away with how long the spot stays clean, so it answers whatever fires first and moves again before the next one does. Two of those hits were a passive beam ONE stud away that we had marked as not yet firing, with the nearest live beam six studs further off: the timing was wrong, not the shape. Being hurt beside a box that has not fired now pulls that attack's window forward, while being hurt beside a live one still pads its shape. The mage shot and the spread beam are padded by what his run measured, 2.5 and 1.5 studs. A dead boss's attacks are ignored for bossDownQuiet seconds, so the missiles already in the air stop counting. Melee mobs are fought from 26 studs rather than 34, since they only reach 16, and the strafe circles toward the rest of the pack instead of away from it. And the hop is considered a little earlier in the run-up to a hit, with the speed burst starting earlier too; how often it may hop and how long a burst may hold are unchanged, since those are what keep the anti-cheat quiet." },
    { version = "6.6.88", date = "2026-09-04", notes = "Two from Chris. The Extra cast range slider goes negative now, from minus twenty to plus forty, so the blue ring can be pulled in as well as pushed out; the reach can never fall below twelve studs whatever it is set to. And low detail can delete scenery rather than hide it, which is a good deal faster: the same non-collidable decoration it was making invisible, plus this map's named decoration removed whole. What it will not do is delete anything you can walk into, or clear the terrain, or rebuild geometry out of CFrame parts. That is the part of the script Chris sent that he says is buggy, and it would also leave the character walking where the server still has a wall, which is exactly what an anti-cheat watches for. Deleted scenery cannot be restored when the mode goes off and the toggle says so." },
    { version = "6.6.87", date = "2026-09-04", notes = "Five from Chris, and one bug of mine his recording found. The slam: an early arm from the Model was passing its start time to any later slam as well, so a second one inherited a fuse that had already run out and the escape thought it was nearly done. A death in his run has the character 33 studs from where the reflex was running and 29 studs inside the box that actually landed. A start is only inherited within half a second now. Low detail was hiding the damage parts, because an attack hitbox is not collidable either and the scenery rule hid anything that was not. Nothing that can hurt you is touched at all now: every catalogued attack, anything the reader is tracking this instant, anything named like a projectile or a telegraph, and the mechanics you have to use, Bob's three crystals among them. Scenery is only hidden on the first pass over the map, never during a fight. Bob is held at the middle of his three crystals again, free within bobHomeSlack studs and costed per stud beyond, so all three stay within easy reach; the keep-away from him never pushes past the crystals themselves. A boss going down clears every tracked threat, since its last attacks lie in the world with open windows. And an open stretch longer than sprintFrom studs with nothing warm ahead is run rather than walked." },
    { version = "6.6.86", date = "2026-09-04", notes = "From the recording Chris sent, a full run to Odin with eight deaths. Two of them were the character standing perfectly still with its speed at zero for six or seven tenths of a second while the state still read in range: that is the cast animation rooting it, and a mage volley landing during the root. A cast now needs castHold seconds of clean ground ahead of it, 0.9 by default, rather than half a second. Two more were taken with nothing on us at all, the nearest mage shot 3.8 studs away: the box is drawn smaller than the attack reaches. So geometry is now learned the way timing already is. Being hurt while outside every box pads whatever was nearest by the size of the miss, once, capped at missHitMax studs and remembered across runs in missHits. The recording also shows the real shape of the problem: through nearly every death only two of two hundred and sixteen nodes were usable, at the Champion as much as at Bob. The circle fix in 6.6.82 cleared that at Bob, measured; the Champion still needs the same treatment and the node probe will name what is doing it." },
    { version = "6.6.85", date = "2026-09-04", notes = "Four from Chris. A slider for the blue ring: Extra cast range adds studs by hand on top of whatever the range has measured, and the drawn ring, the cast gate and the standing distance all follow it together. Bob is now fought from as far as the cast still reaches rather than the standard thirty eight studs, and ground closer to him than the Keep away slider costs per stud, because his nukes spawn on him and his beams go out in every direction: distance is the answer to both. His spinning laser and cross beam count from the moment they appear rather than from a guessed delay, with the seed as a floor the learning cannot push later, since a sweep already hurts wherever it is. And speed: walking to the field's chosen spot IS the dodge, so it is always run at escape speed now, and a burst may start with 1.4 s left before a hit rather than 0.9. How long a burst may hold is unchanged, which is the part that keeps it out of trouble." },
    { version = "6.6.84", date = "2026-09-04", notes = "Low detail mode (Chris), in the Overlays window. The map is stripped to plain shapes: every surface matt and untextured, decals off, particles and trails and beams off, no shadows or fog or atmosphere or camera effects, still water, and anything you cannot walk into made invisible. Each part is its own toggle under a master switch, the way streamer mode works. Nothing is deleted or unparented and no collision or position is touched, because the bot raycasts against this same world to decide where it can stand, so it plays exactly as before; only appearance changes, and every value is put back when the mode goes off or the script is closed. The attacks keep their own visuals unless you tick the last switch, and the bot's own overlay is never touched." },
    { version = "6.6.83", date = "2026-09-04", notes = "Nine deaths watched end to end at 6.6.82, and the node probe says the circle fix held: the predicted circles are gone from the blame list entirely and the ring went from nothing usable to a hundred of its hundred and ninety six nodes. Four hops in the whole run, so the kick was not the hops. What the deaths show is a timing fault, not a dodging one. Three separate attacks killed the character BEFORE the window built from their own touch samples opened: the Champion's passive beam by 0.7 s, Bob's spread beam by 0.8 s, his circle hitbox by 0.4 s. Those samples are of a later part of a volley than the one that lands on us, so more touch data will never fix it. Being hit early is now itself a measurement: health lost while standing inside a box that has not opened yet pulls that attack's window forward by exactly that much, and it is remembered across runs in earlyHits alongside the learned windows." },
    { version = "6.6.82", date = "2026-09-04", notes = "The arena going red, and the kick, both measured live at Bob on 2026-09-04 with the new node probe. The probe found four predicted circles of radius 50 to 55 live at once, all lethal, while the circles actually on the ground were radius 15 and 21: with a candidate ring of 30 studs every single node was inside one, which is why the dots all went red and the bot then stood still. The chain now looks four circles ahead rather than nine, a predicted circle is never more than twenty studs wider than the one actually seen rather than capped at a hundred and ten, and only the next circle is lethal, the ones after it cost instead. The line strip is capped against the real circle too. The kick: 6.6.80 let any urgency start a speed burst inside its rest, and at Bob everything reads as urgent, so the character ran at full speed for up to nine seconds unbroken. Only a reflex may do that now, for at most three seconds, which still covers a whole slam; ordinary urgency gets 2.5 s then rests. And the spread beam that killed four times: its measured window opens 0.8 s after it actually hits, because the touch samples are of a later beam in the volley, so its seed is now a floor the learning cannot push later." },
    { version = "6.6.81", date = "2026-09-04", notes = "The run of 2026-09-04, watched end to end. The slam escape from 6.6.80 works: both escapes cleared the box at twenty studs a second with no pull-back, against nine to thirteen before. The four deaths and the kick were other things. The kick: five hops in thirty four seconds at the Champion, two pairs 3.7 and 3.8 s apart, because a slam or jump hop was allowed to skip the wait after an ordinary one. That exception is gone, the budget at a boss is two a minute rather than four, and no two hops may be closer than five seconds. The pull-back is now seen wherever it happens, not only during a slam: more than six studs in one frame that was not our own hop is the game's guard, it is named in the log, and it stops every hop for thirty seconds. First death: a clean slam escape that finished inside a criss cross lane. An escape heading is now graded on where it ENDS as well as how fast it leaves, and one ending in something lethal is a last resort. Third and fourth deaths: standing ten studs inside four overlapping ice spike fields at Bob, stunned, killed by a spread beam. The spike field is 0.9 rather than 0.55, since a stunned character cannot answer anything that follows, and the spread beam hits as its Model appears rather than 0.8 s later, which is what the deaths measured." },
    { version = "6.6.80", date = "2026-09-04", notes = "Three from Chris, all measured from his own runs. The slam at the Champion: of four recorded escapes not one ran at full speed, they averaged nine to thirteen studs a second against the twenty two a person makes, and the traces show why. The box can replicate a frame or two after its Model, and nothing armed the run until it did, so the character kept walking IN for the first six or seven tenths of a two second fuse; the run is now armed by the Model itself and refined when the box lands, keeping the same start. The rest between speed bursts could fall inside the escape, and the game writing its own walking speed back after a cast was read as a slow, which put the burst to sleep for two seconds; neither can happen during a reflex now, and only a real slow counts. A cast roots the character, so no cast is started into a slam or a fan at all. The hop was making it worse: twice the game pulled the body back about seven tenths of a second later, once from 29 studs out to 19, so the hop is kept only for when the legs cannot make the edge in the time left, a pull-back is detected and named in the log, and after one there is no second hop. The slam also never runs past the centre of its own box. Groups: the aim point is searched over the whole cluster rather than two guesses, and a group whose centre sits just outside the reach is now walked into rather than abandoned for one body, up to groupStepIn studs. Odin: an arc is six studs thick, not twelve, which is what left no clear ground anywhere in the arena, and the radius to hold is the nearest band between two ring radii instead of one fixed 96. Ring sets are logged." },
    { version = "6.6.79", date = "2026-09-04", notes = "Bob goes back to the 6.6.45 mechanics, which fought him well (Chris). Everything I layered on since then made him worse and is gone: the cost on ground near an orb, the cost on any spot he could not be hit from, the run from an orb with no known crystal, the orb outranking the walk in, the bubble at 0.9, the home point moved to the middle of the crystals, and the stronger crystal pull. His home point is again the band distance from him toward the crystals, the orb pull is 0.2, the bubble is 0.45 and the straight run from an orb starts at fourteen studs. Between the avoidance cost and the extra reflex the bot was hopping at nearly every attack and never reaching a crystal, which is both the teleporting and the orbs going unled. Nothing outside Bob is touched: the walls, the circle clamp, the ice spikes, the reach bonus, the beams and the hop limits all stay as they are." },
    { version = "6.6.78", date = "2026-09-04", notes = "Bob, and the kick. Two circles of one chain grow about six studs apart, but circles from different chains were being compared, which gave a growth in the tens, and the chain prediction multiplies growth by nine: it was predicting circles two hundred studs across and painting the arena lethal, which is why every node went red with nothing near it and the bot then stood still and hopped. Growth beyond twelve studs is rejected and no predicted circle may exceed a hundred and ten studs. The ice spike field was fifteen separate attacks once its Model's window closed, because each mesh inside it became its own box; a part inside a catalogued attack Model now belongs to that Model whether or not it is being tracked. And the hop goes back inside the limits that never drew a kick: four a minute at a boss, four and a half seconds apart, with an absolute floor of three seconds between any two hops including the slam's. The extra reach stays." },
    { version = "6.6.77", date = "2026-09-04", notes = "Why it walks into the beams. When the bot stands inside something lethal, the scoring discounted the danger of every sample along a candidate walk for as long as its grace lasted, so that once it was inside one beam, crossing a second one cost nothing and the walk out ran straight through it. The discount exists to let it leave the ground it is on, so it now applies to the first fifth of a second of the walk and no further. Hallways: the walls either side of the direction of travel are measured and the aim point shifts toward whichever side has more room, both on a straight walk and between path waypoints. And being wedged against something with a box arriving now counts as desperate, so the hop can bail it out rather than waiting for its usual budget." },
    { version = "6.6.76", date = "2026-09-04", notes = "The criss cross (Chris: it is not registering some of them). Three things were against it. A bare projectile part was not marked as a floor attack, so its box was height-checked against the ball's centre, which rides above the character: a ball that was certainly going to hit could fail that test and never count. Anything that travels along the floor is marked as a ground attack now. The lane a moving projectile owns reaches 1.8 s ahead of it rather than 1.0, which at thirty studs a second is the difference between twenty seven studs of warning and fifteen. And the zone list held ninety six entries while the Champion announces ten criss crosses at once, each alive eight seconds, so the oldest live paths were being pushed out; it holds two hundred and forty. The announced path is also nine studs to a side rather than seven and a half." },
    { version = "6.6.75", date = "2026-09-04", notes = "The dodge system came back. In 6.6.70 I edited the settings line that begins with dodgeHysteresis and ended my replacement with a comment, which swallowed the rest of that line: dodgeDangerWeight, dodgeDistanceCost, dodgeSafeDistanceCost and dodgeSafeWorst all became nil. The first line of the spot scoring multiplies by dodgeDangerWeight, so it threw on every candidate of every tick from 6.6.70 onward. That is the whole dodge system gone: no spot, no hop, and an overlay frozen where it stood. The four settings are restored on their own line. Also in this build, the move to a dodge spot triggers on the danger looked ahead through the dwell rather than on danger at this instant, which stopped working when the measured windows narrowed." },
    { version = "6.6.74", date = "2026-09-04", notes = "The dodge system, found. The bot only walked to its dodge spot when the ground under it was lethal at that instant. That was fine while a measured window ran a second and a half, because lethal arrived early enough to walk out of; since 6.6.59 narrowed every window to about half a second around the true hit, lethal arrives a quarter of a second before impact and there is nowhere to go in that time. So it stood still and took the hit, and the better the timing measurements got the less it dodged. It now moves on the danger looked ahead through the dwell, and on the grace, which is what the field has been computing all along." },
    { version = "6.6.73", date = "2026-09-04", notes = "The safety spots are drawn solid (Chris: still cannot see the green and red nodes). Only a handful of spots are floor-checked in any frame, and every spot that was not checked was drawn at 0.7 or 0.85 transparency, which on a dark floor is close to nothing; the colour is known for all of them, so they are all drawn solid now, and no dot may shrink below half a stud whatever the marker slider says. The HUD status also reports the overlay: how many attacks are tracked and how many spots are being drawn, or the words spots off if the toggle is off, so the next report says which of the two it is." },
    { version = "6.6.72", date = "2026-09-04", notes = "The regression, found. Luau refuses %d for a number that is not a whole one, and the wedge finder reported its angle that way, so every single time it found a wedge between the beams the whole field threw: no spot, no hop, and stale nodes on screen. It has been firing constantly since 6.6.64 taught the reader to see the beams of the fan again, which is why the Champion got worse exactly as his detection got better. Every format of that kind is now written for a fraction. The field's own errors were logged and nothing else, which is how this hid: they go on the HUD in red with the rest now. And the arena centre taken from the Champion's beams is forgotten twenty seconds after his last one, instead of being carried into the next boss's room and putting the arena rule round the wrong point." },
    { version = "6.6.71", date = "2026-09-04", notes = "Odin gets the same fourteen studs of extra reach Bob has, since both bodies are huge and a cast aimed at the root lands from further out than a range measured on a mob; the drawn ring follows it for either of them. And the routing overlay, the path nodes and the safety spots, is drawn inside its own guard: a single bad candidate used to throw and take every drawing on screen with it for as long as the fault lasted, which is what made the nodes disappear. If it throws now the rest still draws and the HUD names the section." },
    { version = "6.6.70", date = "2026-09-04", notes = "The bouncing (Chris: it oscillates between two spots when something spawns in the way). A spot whose approach closes is now remembered for a second and costs extra while it is remembered, and switching targets needs a clearly better option than before, so the bot carries on searching instead of swapping back to the spot it just left. Bob's circles never take a touch test, so their window is a guess: the padding round a live one goes from ten studs to thirteen. And his walls warn twice as far, four seconds rather than two, but at two thirds the weight, so a wall that far out is something to drift away from rather than flee." },
    { version = "6.6.69", date = "2026-09-04", notes = "Bob gets fourteen studs of extra reach while he is the target, since his body is huge and a cast aimed at his root lands from further out than a range measured against a mob; the drawn ring follows the bonus, so what you see is still what it casts at. His walls warn 2.2 s ahead rather than 1.5, and a spot inside the span of an oncoming wall now costs a quarter point per stud, so the bot leaves off the end of a wall instead of running along in front of it. And the ring of candidate spots is finer, six rings of thirty rather than five of twenty four: the gaps between rows of mage shots are about seven studs and the old spacing could step straight over one." },
    { version = "6.6.68", date = "2026-09-04", notes = "The slam circle always gets its hop (Chris). It was tried only in the first six tenths of the reflex and could be refused by the cooldown or the per minute budget, and if no landing point was completely clean it gave up silently. It is now tried for the whole two seconds of the slam, it ignores the budget, and if nothing is clean it takes the least dangerous point that still has floor and a clear walk. Still one hop per slam, and the speed burst runs the whole way out." },
    { version = "6.6.67", date = "2026-09-04", notes = "Loading the script again now stops the copy that is already running. It never did: the old copy kept its Heartbeat loops, so every reload added another reader, another field and another brain, and the brains issued conflicting movement to the same character every frame. After a session of reloads there could be a dozen of them, which is very likely why the dodging kept getting worse the longer a session went on, and why the window sometimes showed the version before last." },
    { version = "6.6.66", date = "2026-09-04", notes = "Bob. He was taking almost no damage because leading an orb to a crystal parks the bot outside its own casting range, and nothing outranked that: a spot he cannot be hit from now costs sharply, so the bot stays where he is inside the ring while it leads. The drawn range ring is the distance a cast actually reaches, so a boss touching the blue ring really is a boss being hit. An orb of an unfamiliar colour is led toward the middle of the three crystals instead of being ignored, and the pull toward a crystal is stronger, so the bot starts moving the moment one spawns. And his walls get more warning back: the lethal band reaches a second and a half ahead of them rather than 1.1, with the lane drawn 1.2 s out." },
    { version = "6.6.65", date = "2026-09-04", notes = "The hop was switched off at the Champion. It refuses any fight whose target is more than seventy studs away, a limit set when the bot stood on top of a boss; he is now fought from seventy four and his fan from ninety, so for almost his entire fight the blink could never fire (Chris: it is not escaping things it could easily blink out of). At a mapped boss the hop now reaches a hundred and forty studs, comes off cooldown in three and a half seconds and may be used six times a minute. And a wedge finder for his beams: they are full lines through one hub, so the safe ground between them is a wedge that widens with distance. Sorting the bearings of the beams cast in the last second and a half gives the widest gap directly, and its middle at the radius the bot already stands at is the safe spot the ring of candidates kept missing." },
    { version = "6.6.64", date = "2026-09-04", notes = "Three fixes and an alarm. The Champion fires eighteen beams in four tenths of a second from a pool of Models, so most are re-aimed while their previous record is still live; re-tracking only happened once the old record had expired, so those beams were never registered and the fan went unseen. A re-aim now counts as a new attack whenever the beam turns. The spearman's spear is suppressed for six seconds after its hitBox Model is seen rather than only while that Model is tracked, which is what let it draw a second box after the strike fired. The hop distance was fixed at eight studs, which cannot clear a thirteen stud beam lane, so it often found nowhere to land: it is eleven by default, the rings scale with it, and the slider goes to fourteen. And any stage error now shows on the HUD in red instead of only in the console, so a silent fault like the last one cannot hide." },
    { version = "6.6.63", date = "2026-09-04", notes = "Emergency fix for a fault I shipped in 6.6.59. The ping lead I added to the measured windows reads DG, which belongs to the field module; the reader does not import it, so every attack with a learned hit window threw while being tracked. That is the passive beams, the mage shots, the slam, the line shots and both of Bob's beams: none of them were tracked at all, which is why nothing was detected. It also un-suppressed the spearman's spear, since its hitBox Model failed to track and the bare part is only skipped while that Model is there. The reader reaches DG through S now." },
    { version = "6.6.62", date = "2026-09-04", notes = "The dodging regression (Chris: it stopped detecting mob attacks) was mine, from 6.6.51. I had listed the spearman's spear and the warrior's blade as visuals to be skipped, on the grounds that a separate hitBox Model carries their damage, and I guessed at a couple of other names too. When no such Model existed the attack went completely untracked. A listed part is now skipped only while its own hitBox Model is actually being tracked beside it, and the guessed names are gone. A boss missing from one enemy scan also wiped every hazard we knew; that only happens now when the boss is genuinely dead. The Champion's arena is measured from the hub his beams turn about, which is the middle of the floor and does not move when he jumps: past the arena radius costs four times what it did, and fifteen studs past it is never a spot. There is a slider for the radius." },
    { version = "6.6.61", date = "2026-09-04", notes = "Four from Chris. A Marker size slider scales every dot drawn on the ground, the spot candidates, the blue path nodes and the range ring. The projected area of the next cast has its own toggle rather than riding on the range ring. Gathering: with three or more melee mobs spread wider than the ability covers, the bot backs away from the middle of them so they bunch into a column behind it and one cast takes the group; it only does this while the ground is calm and stops as soon as they are tight enough." },
    { version = "6.6.60", date = "2026-09-04", notes = "Bob's walls (Chris: far too scared of them, they are much slower than it thinks). Three things. The wall's speed came from a single frame of movement, so one jittery sample doubled it and threw the predicted wall a dozen studs ahead of the real one; it is smoothed now. Ground that a moving body only reaches after 1.1 s is warm rather than lethal, since 340 studs over 18 s is under 19 a second and there is time to walk off it. And the wall box is a little thinner, with its lane predicted 0.9 s ahead rather than 1.2." },
    { version = "6.6.59", date = "2026-09-04", notes = "The measured windows are built around the median hit rather than the spread of samples (Chris: it dodges the first boss badly). An attack hits at one instant, but with a dozen samples the tenth and ninetieth percentiles are still nearly the minimum and maximum, so a passive beam measured between 0.45 and 1.52 was treated as lethal for a second and a half and the whole arena read as danger. Each attack is now lethal from 0.28 s before its median hit to 0.22 s after, widened by the lag, and the predicted sweep lanes match. Casting is held only when something lands within half a second, instead of whenever the ground was warm or would go hot later." },
    { version = "6.6.58", date = "2026-09-04", notes = "Streamer mode covers the rest of the interface (Chris). Reading the live GUI tree showed four things it was leaving on screen: the level chip over your head, the level and your avatar portrait on the HUD, the gold, gems and XP row, and the command console, whose prompt prints your username. The level and portrait are hidden with the rest by default, the currency row has its own toggle, and the console prompt goes with the name. The level chip is hidden by its bordered container, not just the number, so no empty border is left floating." },
    { version = "6.6.57", date = "2026-09-04", notes = "Five from Chris. The slam: its hit is exact two seconds after the Model appears, so until then the ground under it read as perfectly safe and the bot wandered back inside once the reflex ended; the whole circle is warm from the moment it appears, which also puts the speed burst on early. The burst no longer takes its rest period while a box is about to land, and the hop gets a shorter wait between tries when a box is on us, it fires within a third of a second and the field has found nowhere to walk. The spread beam was asking for an eight stud margin through slim, which only ever caps the margin, so it was being treated as bare: it grows by four studs instead, covering the deaths measured 7.8 studs outside it. A boss within two casts of death is finished rather than dodged, using the biggest health drop seen on it as the measure of a cast. And everything a boss threw is dropped the moment it dies, since none of it damages any more." },
    { version = "6.6.56", date = "2026-09-04", notes = "Three from Chris. Ice spikes stand for ten seconds as a wall after they fire, and their precast is already the full circle, so the whole footprint is now a warm zone for the life of the Model and the bot stops dodging into ground it cannot leave. Group targeting aims at the point covering the most mobs instead of demanding that every one of them fit: a single straggler used to send the cast back onto one mob. And the hop is encouraged against the mapped bosses, with a window of 0.9 s rather than 0.6 and half a second of margin on the walk test, since a beam the legs only just clear is the one that kills." },
    { version = "6.6.55", date = "2026-09-04", notes = "Three from Chris. The blink answers mob attacks now, for the wall of mage shots that closes every gap within walking reach: one hop at a time, nine seconds apart, twice a minute at most, and only with a box already on us, since the kick came from seventeen hops in pairs three seconds apart. There is a toggle for it beside the blink switch. Bob's home point is the middle of the three crystals rather than a spot below him, costed per stud beyond fifteen, so every colour is about the same distance away and the bot drifts back to the middle whenever nothing threatens it. And it no longer walks in just to attack: while the target is inside casting reach it stands and casts, and the field owns the feet." },
    { version = "6.6.54", date = "2026-09-04", notes = "Fix for a fault I introduced in 6.6.51: the table of visual-only parts was declared below the function that reads it, so it was nil there and every part named terrain threw. The reader stage died on that error each tick before it scanned for enemies, which left the bot with nothing to target and standing still (Chris: it is not moving at all). The table is declared above its use now." },
    { version = "6.6.53", date = "2026-09-04", notes = "Five from Chris. The Champion's passive beams: the margin round them was 2 studs while the round trip to the server is over 3 at 135 ms ping, so the bot cleared them by less than the lag and walked into them; the margin is 3 plus a measured ping lead (capped at 4), and a pooled beam re-cast within half a second is now re-tracked, which it was not. Target priority gains Biggest group, which fights the mob with the most others inside the ability area instead of picking off melee one at a time. Bob's wall crawls, so its lane is predicted 1.2 s ahead instead of 3, and the drawn strip matches. Cast only when safe is on by default: the cast animation roots the character, so dodging now interrupts attacking. The crystal keep-out is three points per stud starting 40 studs out (capped so it can never buy a death), and any dodge heading back up toward Bob costs a little." },
    { version = "6.6.52", date = "2026-09-04", notes = "Bob's homing orb is priority one (Chris: it went in for an attack with the nuke closing). The orb is tracked whatever its colour and whether or not its crystal is known, so an unmapped colour no longer goes ignored. Ground within 34 studs of it costs, its bubble is nearly lethal rather than mildly warm, the field's spot outranks walking in to attack while an orb is within 55 studs, and the straight run away starts at 20 studs instead of 14. The crystal keep-out starts 26 studs before the line instead of 10 and costs a full point per stud." },
    { version = "6.6.51", date = "2026-09-04", notes = "Four from Chris. The spearman's flying spear and the warrior's blade are visuals: the damage is in a separate hitBox Model, and boxing them too drew a second box beside the real one and left it lying there a second after the strike fired. Bob: the arena splits at the three crystals, and past that line the bot stands on the wrong side of its own delivery point, so spots past it cost per stud (lifted while an orb is being led). When nothing within the rings survives there are now two ways out before giving up: across the lane, stepping two studs at a time along the axis of the nearest narrow attack until the ground is clean at the moment of arrival, which finds the gap in a wall of shots instead of waiting to be standing in one; and a far sweep out to as much ground as the remaining grace allows, up to 110 studs, for the big slow attacks that cover everything nearby." },
    { version = "6.6.50", date = "2026-09-04", notes = "The wall of mage shots, the real cause (Chris: it is not finding safe spots that exist). A shot's hitBox is 7 studs wide, but it was padded 3, then given the 4-stud body margin and a 2.5-stud shoulder: 21 studs of lethal ground and 26 of warm per row, against rows about 20 studs apart. Consecutive lanes overlapped and no safe spot existed anywhere on the floor. The pad is gone and the shot keeps a 3-stud margin, which still covers the measured deaths 2.1-2.9 studs outside the box; any narrow attack (10 studs or less) now gets the same cap instead of tripling in width." },
    { version = "6.6.49", date = "2026-09-04", notes = "The wall of mage shots (Chris: it has no idea what to do and every node is red). Each shot is its own box, and they land in rows a tenth of a second apart, so no spot stays clean for the whole 1.5 s dwell: every candidate scored lethal, the costs tied, and the bot either stood still waiting for a gap that never came or stepped into the next row. Each spot now reports how long it stays clean after arrival, and when nothing survives the dwell the field takes the longest-lived spot, which is the gap between two rows. Standing still is kept only while here outlasts the best gap." },
    { version = "6.6.48", date = "2026-09-04", notes = "Spots (Chris: red nodes where the ground is clearly safe): a candidate that only failed the wall sweep was drawn in the live colour, so on a bridge or beside a rock the screen filled with red over safe ground. A wall in the way or a missing floor is grey now; red means danger and nothing else. The volley predictor also kept one shared last shot, so two mages firing within 0.4 s of each other fabricated a 240-stud lane between them that neither had fired; it tracks a volley per mage." },
    { version = "6.6.47", date = "2026-09-04", notes = "The same for predicted zones (the volley lane, the beam and circle predictions): they are pruned half a second after they end, so they left a spent lane in the list and on screen; they leave it when the window ends." },
    { version = "6.6.46", date = "2026-09-04", notes = "Detonated attacks (Chris): a Model that lingers after it fires kept its box in the hazard list for the whole linger - the mage shot sits 7 s, Bob's beams 5 s - so a stack of spent shots was drawn and labelled live over the path. The box now leaves the list the moment its window ends, and a box shown past its window reads done, not live. Odin: his dozen bouncing orbs were boxed lethal for their whole 20 s life and walled the arena off; they are warm now." },
    { version = "6.6.45", date = "2026-09-04", notes = "Odin: the ring arcs kill as they appear (a death 4 studs outside two bands at the instant a set spawned) and are about 12 thick. With rings every 12.5 studs on alternating sides, the one radius clear of every possible set is about 96 from the arena centre, between the 87.5 and 105 rings: the field now pulls the bot onto that band, and the arcs are 12 thick." },
    { version = "6.6.44", date = "2026-09-04", notes = "Bob: the orb closes at about 30 studs/s (30 to 14 studs in 1.3 s against a bot at 16-22) and caught the bot twice more while the speed burst was resting at 16. The burst never rests while an orb is out, the lead starts the moment an orb exists instead of at 160 studs, and the pull toward the crystal is stronger." },
    { version = "6.6.43", date = "2026-09-04", notes = "Bob (Chris: it forgot the orb again): the lead ended when the orb came within 22 studs of its crystal, but the orb follows the player, not the crystal, so it turned and followed the bot back out. The lead now holds until the orb is 5 from the crystal, about to touch it." },
    { version = "6.6.42", date = "2026-09-04", notes = "Slam: the probe shows the box never moves; the runs failed on radial speed (12 studs/s out of 22) because the exit heading kept switching. The kept heading now wins unless another is 15 studs shorter, and the step check looks 0.4 s further on (a criss cross reached the step after the check)." },
    { version = "6.6.41", date = "2026-09-04", notes = "Odin (Chris: it will not go into the arena): the ring arcs flash for about 1.5 s after they appear and then sit invisible for 20 s; the arc zones lived 12 s each, so eight sets painted the whole arena. They live 1.8 s now and are 10 thick (a death 5 studs outside a 6-thick band). The sideways missile box is 24 x 44 (one 12 studs away killed with the old box clear)." },
    { version = "6.6.40", date = "2026-09-04", notes = "Champion: the criss cross that spawns on the player 1.2-1.3 s after Jump Up gets a hop in that window (the one reaction there is); hops out of certain death take warm ground (the slam hop found 48 of 48 spots hot from criss cross lanes); a slam run stopped against something drops that heading. Bob: the orb run heads for the crystal and refuses lanes (it ran into the wall). Recorder: the slam hitBox is tracked after spawn - the traces show it follows the player." },
    { version = "6.6.39", date = "2026-09-04", notes = "Odin, from the part probe: the multirings are eight invisible static parts round the arena centre (30 studs from his root), radii 25 to 105 in 12.5-stud steps as half-ring arcs on alternating sides, a new set at a new angle every second, each alive 4-8 s. Each arc is now its own annulus zone (6 studs thick, its own half), gone when its Model goes; the bands between rings are the ground to stand on." },
    { version = "6.6.38", date = "2026-09-04", notes = "Odin, first data: a new set of concentric half-rings every second, each alive 20 s - as solid lethal boxes fifteen of them painted the whole arena hot and the field went blind; they are warm (0.35) until the arcs are understood. Line shots measured: one hit at 0.85-0.89 s after the pair appears, seeded exact. The orb explosion zone is 20 (the bot stood 7.6 from one and lived)." },
    { version = "6.6.37", date = "2026-09-04", notes = "Bob: an orb closing to 14 studs starts a straight one-second run away from it at full speed (the field with its detours let the orb catch the bot: a stun, then a beam, three times today)." },
    { version = "6.6.36", date = "2026-09-04", notes = "Champion (Chris: too many deaths, it gets caught or stays put and an attack spawns on it). The traces show the combo: Jump Up, 1.2 s later a criss cross spawns on the player, 0.8 s after that the slam Model lands on him. Jump Up now starts a straight run along the tangent, so a snapshot position is left behind and the slam run begins with momentum instead of from a dither. Inside a reflex only a lethal step is refused: a warm lane bent the run sideways inside the slam (deaths at 26-28 of 56). The blink records why it found no spot." },
    { version = "6.6.35", date = "2026-09-04", notes = "Mobs (Chris: it picks them off one by one): the walk now closes on the centre of the group inside the AoE, so the cast at the standoff lands among them. Bob: both deaths this round were the orb catching the bot (stunned inside its bubble, then a beam); the bubble is 17 studs and 0.75 warm so no spot inside it beats hot ground." },
    { version = "6.6.34", date = "2026-09-04", notes = "Bob (Chris: it runs into his ground attacks while an orb is coming): the pull toward the crystal was unbounded, 60 studs of it outweighed standing in a live circle; it is bounded to 25 studs and fades on ground that is not clean. Champion, round four: the slam run flipped between two equally near faces every tick and covered 21 studs in 1.8 s at full speed (the heading kept from the last tick earns a bonus); a seeking spike arrived 5.4 s after the slam hop with the blink still on its 6 s cooldown (4.5 s now, four a minute); the field sent it to 124 from the hub during the fan, four studs from the kill zone (past 108 is never a spot)." },
    { version = "6.6.33", date = "2026-09-04", notes = "Casting (Chris: it strafes back and forth and will not use its ability): the range gate used the aim point, which leads a moving target; at a 74 standoff the lead sat at 85 against a reach of 81 and nothing was cast for minutes. The gate is now the nearer of the aim point and the body. Odin groundwork (Chris: start getting his attacks). The hit windows the touch test measures now travel with the config, so a boss learned in one fight is known from the next. His orb explosion event (a 90-stud ball at the orb) is a zone. He has a profile that keeps the bot inside his arena." },
    { version = "6.6.32", date = "2026-09-04", notes = "One fix per death of the watched round. Range: the seed ran before the Tools existed and never again, so every run started from 46-49; it retries and a slot first seen by its cast starts from the remembered range. Mages within 90 count as aggro (it stood still waiting beside one and the volley landed) and the mage shot is padded 3. The slam run ends four studs clear of the box and never heads past 105 from the boss (it ran to 140 and the arena killed it). The fan is 18 lines 10 degrees apart within 0.4 s, all 8 x 250 through one hub: no chain predictions during a burst (phantom lanes), the beam reads 8 wide (slim 2), the fan radius is 90 where the gaps are widest. Bob's circles march out 26 a step and shrink 6 (the fallback grew them both ways). Hot ground keeps its heading unless a spot is clearly safer (five reversals in 3 s let the wall walk over it)." },
    { version = "6.6.31", date = "2026-09-03", notes = "Travel (Chris: stuck at the foot of the spiral stair, the pathfinding could not see it had to go round). Waypoints were matched flat, so the loop above counted as reached, the resume scan picked waypoints overhead and every stall skipped further up the spiral while the body pushed into the stair mesh. Waypoints now count height, the resume scan stays on this floor, a stall asks for a fresh path from here before skipping anything, and waypoints the navmesh marks as jumps are jumped." },
    { version = "6.6.30", date = "2026-09-03", notes = "Range: both slots start from the remembered range. Q and E carry the same ability (two Geysers) and the name-keyed seed held only one slot, so the other started from scratch at 49 and the standoff followed it." },
    { version = "6.6.29", date = "2026-09-03", notes = "Fix for a 6.6.26 fault: the slam reflex called a field function that was not visible from the brain, so the brain errored every frame of a slam and released the character - it stood still through two slams this round. Fan mode now lasts four seconds past the last burst (it walked back in between bursts and died in the lanes at 87 studs). No range cap from a missed cast: casts land from 66-72 and a 47 cap had pulled the standoff to 43, where the sweep lanes are three studs apart." },
    { version = "6.6.28", date = "2026-09-03", notes = "Streamer mode: the drawing sweep was destroying the black block every frame it ran (anything in the visuals folder that was not the Hazards folder), so the block flickered in and out; it is spared now." },
    { version = "6.6.27", date = "2026-09-03", notes = "Streamer mode (Chris), in the Overlays window: hides your name, title and VIP tag over your head and on the HUD, the health numbers and bar, the game's player list and Roblox's, other players' nameplates, and the chat; the character is drawn as a black block the size of the field's spot marker with the model and armour invisible. Each part is its own toggle; everything is put back when the mode goes off. Settings are remembered." },
    { version = "6.6.26", date = "2026-09-03", notes = "Fan (Chris: dying on the fan again). The Champion re-aims a pool of parked passive beam Models; a re-aim never moves a full-line hitBox, and the sweep's re-track gate wanted the precast seen off first, so a Model re-cast within a second of its last hit went blind for the rest of the fight (deaths with no beam box anywhere near). Every tracked Model is now watched: its telegraph lighting again, or a parked hitBox turning, re-tracks it that frame. Bob's wall (Chris: still running into the walls coming toward it): a spot on the far side of a wall box is never taken. Slam: the reflex leaves through the nearest face of the 67-stud cube (54 to a corner; it ran the diagonal and died at 40 twice), the head-start hop is tried through the first 0.6 s and may be a fourth blink in the minute. Bob's circles kill as they appear late in the chain; the line strip gets warmer toward its axis so the field walks out sideways. Horizontal beam padding 6." },
    { version = "6.6.25", date = "2026-09-03", notes = "Anti-cheat kick nine, right after an ice-spike slow. The trace shows the character at 11 studs a second with WalkSpeed 22: the game had lowered the speed and the burst forced it back every frame, while a stun part sat on the player and the bot kept issuing moves. A WalkSpeed we did not write is the game's and is left alone for two seconds; with the game's stun part on the player the bot stands still until it is gone." },
    { version = "6.6.24", date = "2026-09-03", notes = "Bob (Chris: it did not run from the geyser): the trace shows the bot 28 studs inside a 92-stud ice-spike zone when it fired, slowed to 11 studs a second, and taken by a spread beam 1.4 s later. The lead the field gives a telegraph now grows with the zone radius (two seconds for the large spikes) so it leaves in time, and a character slowed by the spikes may hop four seconds after its last hop, once per twenty." },
    { version = "6.6.23", date = "2026-09-03", notes = "Champion (Chris: it gets too close to the centre of the arena). A pad round the Champion: any spot closer than 45 studs to him costs 0.2 a stud, fan or not, so the dodging never drifts to the centre." },
    { version = "6.6.22", date = "2026-09-03", notes = "Bob (Chris: it had room on the left and walked through the wall). A wall that is still, or whose velocity is not yet trusted, was boxed along the world X axis, so a wall standing at an angle had no box where it actually stood. The box now lies along the line between the wall's two balls." },
    { version = "6.6.21", date = "2026-09-03", notes = "Bob: the wall Model is placed and then set on its path, and that jump read as a huge velocity for one sample, sweeping a phantom wall across the arena; the bot fled it into the ice spikes and died. The first 0.4 s of a wall are not a velocity and the speed is clamped to 40. The Champion fell with no deaths at all in the run this came from." },
    { version = "6.6.20", date = "2026-09-03", notes = "Champion (Chris: weird teleports, and it cannot do the fan any more). The Jump Down event was restarting the slam reflex, which meant a second head-start hop two seconds after the first; it now keeps the running reflex. Blink destinations are checked clear for 0.75 s rather than the whole dwell: in the fan every spot has a beam within 1.5 s, so nothing ever passed and the blink was gone exactly where it mattered. A box on the character firing within a second counts as hot for the stand-still rule. Seeking spikes are boxed wider; they slow on touch." },
    { version = "6.6.19", date = "2026-09-03", notes = "Range (Chris: still not far enough): a cast landed 52 percent on a spearman from 66-72 studs with the remembered range at 57. The bot now stands five studs past a landed cast rather than three, the cap is 90, and the cast reach is the range plus twelve for the geyser's area. Mobs only: with no ability off cooldown the bot waits 70 studs from a mob that has not noticed us instead of walking up and waking it; a mob already coming is fought as usual." },
    { version = "6.6.18", date = "2026-09-03", notes = "The fan (Chris: get to the fan area as quickly as possible and never drift to the centre). Fan radius 75; while the fan is on, every spot inside that radius costs 0.15 a stud so all dodging trends outward; the fan reflex arms from anywhere inside the radius, runs at escape speed with the burst allowed for the whole run out, and lasts 3.5 s." },
    { version = "6.6.17", date = "2026-09-03", notes = "Champion (Chris: it gets stuck in a corner and the boss jumps onto it). The fan rule sent it to 85 studs, which is the rocks; 70 now. The reflex takes the most open safe heading out of ten, corners included, instead of the first that passes. The slam cannot be outrun from its centre in two seconds, so the first frame of the slam reflex hops eight studs outward while the ground is still clean, and the speed burst may last the whole slam while a reflex is on." },
    { version = "6.6.16", date = "2026-09-03", notes = "Bob's wall (Chris: the slow electric one is accounted for far too early, the bot would not even enter the room): the warm lane ahead of a moving body now reaches only as far as the body gets in three seconds, not its whole remaining path. Blink destinations are checked clear for the whole dwell with the body margin, not one second bare: a box firing at 1.1 s read clear and the hop landed in it (Chris: it teleports into the centre of attacks and stays)." },
    { version = "6.6.15", date = "2026-09-03", notes = "Bob: two deaths 2.4 and 7.8 studs outside the spread beam's 12-wide box, so its padding is 8 (the hit area is about 28 wide). Ice spikes slow the character (5.5 studs a second for over a second, then a beam took it): their zones are six studs wider and held 1.2 s, and the blink's walk test now uses the speed the character actually has. Exact windows open 0.3 s before the earliest measured hit: a bot inside a beam at spawn planned to leave by 0.6 s and died three studs inside." },
    { version = "6.6.14", date = "2026-09-03", notes = "The flashing spearmanStrike boxes: the reader called a spear still under 1 stud/s while the emitter called it moving over 2, so a spear jittering between the two never accumulated its second of stillness and was drawn, dropped and redrawn every frame. One threshold, one owner of the timer, and a projectile that has been still for a second is deleted with its box and label." },
    { version = "6.6.13", date = "2026-09-03", notes = "Bob's orbs, simplified (Chris: it went back and forth between the orb lead and the dodging; as long as it heads the right colour's way it may keep backing up). The orb is no longer a separate drive: it sets a pull on the field toward the spot behind the crystal of its colour, the field's spot leads every frame while an orb is out, and standing still is not an option until that spot is reached. One controller, so no back-and-forth; the bubble keeps it off the orb; within 22 studs of the crystal the orb is done and the home pull toward Bob returns." },
    { version = "6.6.12", date = "2026-09-03", notes = "Never stand on ground about to go hot. Three slam deaths and a beam death were the character standing for the last half second: the reflex gave up when no heading passed the safety check (it now takes the most open heading regardless - inside the slam, stopping is the one certain death), the walk was blocked with no spot, and the in-range branch had no strafe point. All of those now move to the spot, else the best scored candidate, else away from the nearest enemy. The orb lead yields to the field while the ground here is going hot (it walked through a spread beam and stood in the ice spikes)." },
    { version = "6.6.11", date = "2026-09-03", notes = "Bob only (Chris: the crystal is not cover to shoot from, the bot was ending up too far from Bob to hit him). The bot stands six studs behind the crystal, not twelve, and the moment the orb is within 22 studs of its crystal the orb business is over: the ordinary fight resumes and the home point pulls it back into range of Bob." },
    { version = "6.6.10", date = "2026-09-03", notes = "Bob only (Chris): with an orb out the bot goes to the spot behind the crystal of its colour and holds there, shooting Bob, instead of backing away from the orb; it flees only with the orb on top of it and the crystal the wrong way. A walk cut by an attack with no spot to fall back on now takes the best scored candidate instead of standing still: a beam death came from 0.4 s standing beside a beam about to fire." },
    { version = "6.6.9", date = "2026-09-03", notes = "Range (Chris: it reaches further than the bot stands): a cast landed 8.5 percent on Bob from 57 studs. A measured reach is only a lower bound, so the bot now stands three studs past it and probes outward each time a cast lands, and the best range found is saved with the settings and used from the start of the next run." },
    { version = "6.6.8", date = "2026-09-03", notes = "The field runs at 60 Hz instead of once per frame (it took 2.8 ms of a frame that is 4-7 ms at Chris's 140-240 fps) and spends the time on finer sampling: the ground on arrival is checked every 0.15 s through the dwell instead of three times (a 0.4 s hit window could slip between them), path samples every 2 studs, 24 spots a ring." },
    { version = "6.6.7", date = "2026-09-03", notes = "The fan (Chris: it walks over an active path): a measured attack now has an exact window with no lead, so a beam counts as lethal only around its one hit at 0.9 s and is safe to cross before it; predicted lanes the same. Bob: the orb step starts the moment an orb exists anywhere in the arena and casts at Bob while it leads. Death-effect, particle and smoke parts are never labelled. A thrown spear is done a second after it stops instead of live for its whole life." },
    { version = "6.6.6", date = "2026-09-03", notes = "Learned windows are the 10th to 90th percentile of the last forty touch tests, and a sample under 0.3 s is discarded as a Model the sweep caught late: one mage shot read 0.05 s and would have opened its window from spawn." },
    { version = "6.6.5", date = "2026-09-03", notes = "Bob's orb: it closed from 29 to 16 studs in two seconds while the bot walked toward a crystal that lay past it, and exploded. Now: within 26 studs of the orb, or with the crystal not on the far side of the character from the orb, the bot runs straight away from the orb along the most open safe heading; it heads for the crystal only once the orb is behind it and the crystal ahead." },
    { version = "6.6.4", date = "2026-09-03", notes = "Bob's beams from the touch test: the horizontal beam hits once at 1.03-1.08 s (the seed said 0.6, from a misread death), the spread beam once at 0.92-1.20 s, both Models lingering 5 s harmless. Passive beam 0.6-1.15 over 508 samples (0.77-1.10). Bob's circles, the ice spikes, the wall and the criss cross show no touch test on their client parts: their timing stays from the announcements and the deaths." },
    { version = "6.6.3", date = "2026-09-03", notes = "The reflex (slam, fan) takes a heading only when it is both safe and clear of walls, tries 110 degrees either side too, and with none takes the field's spot instead of running blind: it ran into the arena rocks and stood still to die, and ran through a criss cross while fleeing a slam. Mage shot window from the touch test: one hit at 0.75-0.97 s." },
    { version = "6.6.2", date = "2026-09-03", notes = "Anti-cheat kick during the mob rooms: seventeen hops in five minutes, in pairs three seconds apart, against spearmen and warriors. The blink is back to the mapped boss fights only, six seconds apart, three a minute, and the second hop inside the cooldown is gone." },
    { version = "6.6.1", date = "2026-09-03", notes = "Measured, not estimated: the server tests an attack's hitBox with one touch query at the moment of damage, which leaves a TouchTransmitter on the part for a frame. Watching for it on 163 Champion beams gave one hit at 0.92 s after the Model appears (0.39-0.98), the line visible from spawn and gone by 1.1 s, the Model lingering 7 s harmless; the slam hits once at 1.98 s. Seeds set to those windows (the beam was held 3.5 s, which is why the fan had no gaps). Every hitBox attack now learns its own window from that signal after three samples. The cast reach is the measured range plus six, not three: the bot stood at range and strafed out of reach." },
    { version = "6.6.0", date = "2026-09-03", notes = "The ring never scales: when nothing near is clean, four outer rings are added to the near ones instead. Among clean spots the nearest wins by a wide margin (a blink can reach it). A Model whose window ran out is never re-tracked unless it moved or its precast came back: the Champion parks a pool of passive beam Models at the hub for the whole fight, and the sweep re-tracked them every four seconds, so the hub read as firing beams. Show hitbox parts makes the game's own hitBox parts visible; blocked spots name the part the wall sweep hit. Spearman and warrior strikes end with their precast fade (1.5 s at most); the 100-stud zone from their announcement is gone. Bob's following orb: only its body is lethal; the 14-stud bubble round it is warm (0.45), so it no longer walls the bot in with every spot red and nowhere to blink." },
    { version = "6.5.0", date = "2026-09-03", notes = "Five rings of twenty spots, six studs apart (sliders). The walkability sweep is carried at body height with its bottom at the step height, so floor debris and steps no longer read as walls; the same sweep serves travel. Spot colours: red only for lethal ground or a wall in the way, yellow for warm ground the field may still use. Mob attack windows run longer (mage shot 2.5 s, strikes 2.0 s, the volley line 3 s): the bot walked into shots that had fired and died. Each drawn box keeps its own Part, so labels no longer flicker between attacks." },
    { version = "6.4.0", date = "2026-09-03", notes = "Spots: a wall in the way is red and never taken; a wall inside the Wall padding slider is orange, not recommended, taken only when no open clean spot exists. Abilities fire whenever the target is in range; the hold while the ground is hot is now the Cast only when safe toggle, off by default." },
    { version = "6.3.0", date = "2026-09-03", notes = "Rooms are gone: with no mob within 150 studs the target is the nearest enemy anywhere and the walk there is the travel. The room walk threw every frame (rooms are Folders, and the call was outside its pcall), the brain stage died mid-walk and the character kept running the last commanded way with every spot green; a failed brain stage now stops the legs. Melee and ranged mobs have their own standoffs. Player ability visuals (the game's projectiles folder) are never hazards. Every tracked attack can carry its name; anything unrecognised that appears nearby is labelled in grey for ten seconds so its name can go into the catalogue." },
    { version = "6.2.0", date = "2026-09-03", notes = "Catalogued attacks count only when parented straight to workspace, as the game does it: 6.1.0 also took the streamed map's parts named rock and the like as permanent hazards, which left the field with no safe spot and stalled the bot. Each loop stage runs under its own pcall and failures are warned in the console. The white warning outline shows only while the telegraph is visible and the attack has not fired. The ability's AoE is measured from its projectile and drawn where the next cast lands, with the measured range as a ring; the standoff from mobs and bosses is that range less the Range margin slider (replaces Ability radius). Target priority: melee first, ranged first or nearest; the AoE is aimed at the centre of the mobs it can cover with the target." },
    { version = "6.1.0", date = "2026-09-03", notes = "Every enemy attack in the game's enemyProjectiles folder is tracked by name (src/attacks.lua, generated): a Model with no hitBox or precast hurts from its biggest part while it exists; a catalogued part is a hazard while it exists and is visible. Sliders for the body margin and the shoulder in Dodge. Overlays: travel waypoints and the field's spot candidates can be drawn." },
    { version = "6.0.0", date = "2026-09-03", notes = "Rewrite of 5.1.72 in half the code with the same rules and measurements. Hazards are flattened to 2D once a frame and culled by distance, so the spot search costs a fraction of what it did." },
}

if not game:IsLoaded() then game.Loaded:Wait() end   -- the autoexec can run before the player replicates
-- Executing this a second time used to leave the first copy running: its Heartbeat loops kept reading, drawing and
-- above all issuing movement, so two brains fought over the character every frame and the dodging turned to mush.
-- The old copy exposes its own destructor; call it before anything of ours exists (Chris: the GUI still shows the
-- version before last, which is the old copy's window being replaced while the old copy runs on).
if type(_G.DungeonAutofarmDestruct) == "function" then
    local ok, err = pcall(_G.DungeonAutofarmDestruct)
    if not ok then warn("[DQ] could not stop the previous copy: " .. tostring(err)) end
    task.wait(0.1)
end
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
while not LocalPlayer do task.wait(0.1) LocalPlayer = Players.LocalPlayer end
