-- Bob's crystals: by name under secondBossCrystals, else the measured positions.
local CRYSTALS = { red = Vector3.new(-144, 23, 268), green = Vector3.new(-159, 23, 335), yellow = Vector3.new(-105, 23, 377) }
local crystalCache = {}
local function bobCrystal(colour)
    colour = string.lower(colour or "")
    local c = crystalCache[colour]
    if c and os.clock() - c.at < 5 then return c.pos end
    local pos
    local holder = Workspace:FindFirstChild("secondBossCrystals", true)
    if holder then
        for _, d in ipairs(holder:GetDescendants()) do
            if d:IsA("BasePart") and string.lower(d.Name):find(colour, 1, true) then pos = d.Position break end
        end
    end
    pos = pos or CRYSTALS[colour]
    crystalCache[colour] = { at = os.clock(), pos = pos }
    return pos
end
local function bobCrystalCentroid()
    local sum, n = Vector3.zero, 0
    for colour in pairs(CRYSTALS) do local p = bobCrystal(colour) if p then sum, n = sum + p, n + 1 end end
    return n > 0 and sum / n or nil
end

local RT = { farmEnabled = true, destroyed = false, movementState = "starting", tickMs = 0, moveBoost = false,
    lastQ = -math.huge, lastE = -math.huge, lastClick = -math.huge, blinks = 0, blinkTimes = {}, mobBlinkTimes = {} }

-- helpers
local function log(tag, text) if CFG.debugPrints then print(("[DQ %s][%s] %s"):format(SCRIPT_VERSION, tag, text)) end end
local throttle = {}
local function logT(key, seconds, tag, text)
    local now = os.clock()
    if (throttle[key] or -math.huge) + seconds > now then return end
    throttle[key] = now
    log(tag, text)
end
local function setState(text) RT.movementState = text end
local function character()
    local c = LocalPlayer.Character
    return c, c and c:FindFirstChildOfClass("Humanoid"), c and c:FindFirstChild("HumanoidRootPart")
end
local function flatDistance(a, b) local dx, dz = a.X - b.X, a.Z - b.Z return math.sqrt(dx * dx + dz * dz) end
-- One Folder under Workspace holds everything this script draws, so one ancestor test excludes it everywhere.
local function visualRoot()
    if RT.visualRoot and RT.visualRoot.Parent then return RT.visualRoot end
    local f = Instance.new("Folder")
    f.Name = "DungeonAutofarmVisuals"
    f.Parent = Workspace
    RT.visualRoot = f
    return f
end
local function isOurs(inst) return RT.visualRoot ~= nil and inst:IsDescendantOf(RT.visualRoot) end
local function raycastParams(exclude)
    local p = RaycastParams.new()
    p.FilterType = Enum.RaycastFilterType.Exclude
    local list = {}
    if LocalPlayer.Character then list[#list + 1] = LocalPlayer.Character end
    if RT.visualRoot then list[#list + 1] = RT.visualRoot end
    if exclude then list[#list + 1] = exclude end
    p.FilterDescendantsInstances = list
    p.IgnoreWater = true
    pcall(function() p.RespectCanCollide = true end)
    return p
end
local function floorY(x, y, z, params)
    local hit = Workspace:Raycast(Vector3.new(x, y + 6, z), Vector3.new(0, -46, 0), params)
    return hit and hit.Position.Y or nil
end

-- The config file keeps settings only (what the interface exposes); tuning constants follow the code, so a new
-- default is never overridden by an old saved value. Colours travel as hex.
local FILE = "DungeonAutofarm6_config.json"
local PERSIST = { "abilityRadius", "attackRange", "reachBonus", "bossKeepOut", "bossKeepOutWeight", "autoAttack", "autoE", "autoQ", "autoFarmByPlace", "autoQueue", "autoQueueDelay",
    "autoQueueDifficulty", "autoQueueHardcore", "autoQueueMap", "autoQueuePrivate", "autoQueueReplay", "autoStartDungeon", "autoStandoff",
    "blink", "blinkMax", "bonusBoss", "bossStandoff", "mobStandoff", "strafe", "strafeSpeedFraction", "tweenEscape", "tweenWalk",
    "colorFloor", "colorLive", "colorSoon", "drawHazards", "drawTarget", "drawPath", "drawSpots", "drawAbility", "drawAoe", "markerScale", "gatherMobs", "hazardTransparency", "debugPrints", "menuKey",
    "dodgeMargin", "dodgeShoulder", "rangeMargin", "targetPriority", "rangedStandoff", "labelHazards", "labelUnknown", "wallPadding", "castSafe",
    "dodgeRings", "dodgeRays", "showHitboxes", "abilityRangeKnown", "pingMarginMax", "blinkMobs", "arenaRadius",
    "streamer", "streamerName", "streamerHealth", "streamerBody", "streamerOthers", "streamerLeaderboard", "streamerChat", "streamerLevel", "streamerWealth", "learnedHits", "earlyHits", "missHits",
    "reachBonusMob", "reachBonusBoss", "mageMargin",
    "lowDetail", "lowTextures", "lowEffects", "lowLighting", "lowDecorations", "lowAttackEffects", "lowDeleteMeshes" }
local hasFiles = type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
local lastJson, lastSave = nil, -math.huge
local function snapshot()
    local out = { __version = SCRIPT_VERSION }
    for _, k in ipairs(PERSIST) do
        local v = CFG[k]
        out[k] = typeof(v) == "Color3" and ("#" .. v:ToHex()) or v
    end
    return out
end
local function saveConfig()
    if not hasFiles then return false end
    local ok, json = pcall(HttpService.JSONEncode, HttpService, snapshot())
    if not ok or json == lastJson then return ok end
    if pcall(writefile, FILE, json) then lastJson = json return true end
    return false
end
local function loadConfig()
    if not hasFiles or not pcall(isfile, FILE) or not isfile(FILE) then return false end
    local ok, data = pcall(function() return HttpService:JSONDecode(readfile(FILE)) end)
    if not ok or type(data) ~= "table" then return false end
    for _, k in ipairs(PERSIST) do
        local v, cur = data[k], CFG[k]
        if typeof(cur) == "Color3" and type(v) == "string" then
            local okc, c = pcall(Color3.fromHex, v)
            if okc then CFG[k] = c end
        elseif v ~= nil and typeof(v) == typeof(cur) then CFG[k] = v end
    end
    log("Config", "loaded " .. FILE)
    return true
end
local function autosaveTick(now)
    if now - lastSave < CFG.autosaveInterval then return end
    lastSave = now
    saveConfig()
end
pcall(function()
    LocalPlayer.OnTeleport:Connect(function(state)
        if state == Enum.TeleportState.Started or state == Enum.TeleportState.RequestedFromServer then saveConfig() end
    end)
end)

S.SCRIPT_VERSION, S.SCRIPT_CODENAME, S.SCRIPT_BUILD_DATE, S.SCRIPT_CHANGELOG = SCRIPT_VERSION, SCRIPT_CODENAME, SCRIPT_BUILD_DATE, SCRIPT_CHANGELOG
S.Players, S.LocalPlayer, S.Workspace, S.RunService, S.ReplicatedStorage = Players, LocalPlayer, Workspace, RunService, ReplicatedStorage
S.UserInputService, S.PathfindingService, S.VirtualInputManager = UserInputService, PathfindingService, VirtualInputManager
S.CFG, S.RT, S.TIMING, S.PROJECTILE_HINTS = CFG, RT, TIMING, PROJECTILE_HINTS
S.UI, S.sliderConnections = {}, {}   -- the kit tracks widget connections in sliderConnections; the interface tears them down
S.bossProfile, S.bobCrystal, S.bobCrystalCentroid = bossProfile, bobCrystal, bobCrystalCentroid
S.log, S.logT, S.setState, S.character, S.flatDistance = log, logT, setState, character, flatDistance
S.visualRoot, S.isOurs, S.raycastParams, S.floorY = visualRoot, isOurs, raycastParams, floorY
S.saveConfig, S.loadConfig, S.autosaveTick = saveConfig, loadConfig, autosaveTick
_G.DungeonAutofarmState = S
end
    end)()
    module(S)
end

