            position = UDim2.fromOffset(math.clamp(x, 8, math.max(8, vw - w - 8)), math.clamp(y, 8, math.max(8, vh - h - 8))) })
        windows[name] = api
        return api
    end
    local autofarm = win("Autofarm", "Autofarm", 24, 24, 320, windowH, "Everything the bot does while it runs.")
    local dodge = win("Dodge", "Dodge", 360, 24, 320, windowH, "How the field reads danger and picks a spot.")
    local queue = win("Queue", "Auto queue", 696, 24, 310, 540, "The loop outside the fight.")
    local overlays = win("Overlays", "Overlays", 1022, 24, 300, 420, "What is drawn in the world.")
    local configs = win("Configs", "Configs", 1022, 460, 300, 200, "Settings on disk.")

    -- Autofarm
    local body = autofarm.body
    local master = track(K.toggle(body, "Enable Autofarm", function() return RT.farmEnabled end, function(v) RT.farmEnabled = v if not v then releaseCharacter() end end, 1,
        "The master switch. Off in the lobby and on in a dungeon by itself when Auto queue's place rule is on."))
    UI.masterRender = master.render
    local combat = K.section(body, "Fighting", 2, "Range, abilities and the swing.")
    cfgToggle(combat.content, "Auto Q", "autoQ", 1, "Press Q on cooldown while the target is inside the ability radius.")
    cfgToggle(combat.content, "Auto E", "autoE", 2, "Press E on cooldown while the target is inside the ability radius.")
    cfgToggle(combat.content, "Gather mobs", "gatherMobs", 2.9, "With three or more melee mobs spread wider than the ability covers, back away so they bunch into a column behind you, then cast once on the group. Stops the moment the ground here is not calm.")
    cfgToggle(combat.content, "Auto attack", "autoAttack", 3, "Swing the weapon while the target is in reach. Off for high-level dungeons: abilities only.")
    cfgToggle(combat.content, "Cast only when safe", "castSafe", 3.2, "Extra caution: also hold the abilities while the ground here is warm. Off (the default) still holds a cast when something lands within half a second, but otherwise casts whenever the target is in range.")
    local priorities = { { value = "melee", label = "Melee first" }, { value = "group", label = "Biggest group" }, { value = "ranged", label = "Ranged first" }, { value = "nearest", label = "Nearest" } }
    track(K.dropdown(combat.content, "Target priority", priorities, function() return CFG.targetPriority end, function(v) CFG.targetPriority = v end, 3.5,
        "Which mob to fight first in a room. Melee first picks them off one by one and is safest; Biggest group goes for the mob with the most others inside the ability area, which clears a room faster. The AoE is aimed at the centre of the mobs it can cover together with that one."))
    cfgSlider(combat.content, "Keep away from bosses", "studs", 30, 110, false, "bossKeepOut", 4.5, "Bob: ground closer to him than this costs per stud, because everything he throws starts on him. The fight is held at the far edge of the cast range.")
    cfgSlider(combat.content, "Range margin", "studs", 0, 15, false, "rangeMargin", 4, "Stand this far inside the measured ability range, from mobs and bosses alike: the furthest spot from which every cast still lands. Until a cast has measured the range, the built-in radius is used.")
    cfgSlider(combat.content, "Attack range", "studs", 4, 20, false, "attackRange", 5, "The weapon's reach.")
    cfgSlider(combat.content, "Extra cast range", "studs", -20, 40, false, "reachBonus", 5.5, "Moves the blue ring by hand, on top of whatever the range has measured, against everything. Positive casts and stands further out; negative pulls it in, for when the measured range is optimistic and casts are missing.")
    cfgSlider(combat.content, "Extra range: mobs", "studs", -20, 40, false, "reachBonusMob", 5.6, "The same again, but only while the target is a mob.")
    cfgSlider(combat.content, "Extra range: bosses", "studs", -20, 40, false, "reachBonusBoss", 5.7, "The same again, but only while the target is a boss.")
    cfgSlider(combat.content, "Mage shot margin", "studs", 0.5, 4, true, "mageMargin", 5.8, "How much room to keep from the edge of a northern mage shot, body included. The shots in a volley are about eleven studs apart and seven wide, so the gap between them is under four: lower this until the middle of the gap turns green, raise it if it takes clips.")
    combat.setOpen(true)
    local standing = K.section(body, "Standing", 3, "How far from each kind of enemy to fight.")
    cfgToggle(standing.content, "Standoff from ability range", "autoStandoff", 0, "Measure how far your ability reaches from where it lands, and fight bosses from just inside that. The slider below is used until it has been measured, or when this is off.")
    local rangeCaption = K.caption(standing.content, "Ability range: not measured yet", 0)
    cfgSlider(standing.content, "Boss standoff", "studs", 10, 80, false, "bossStandoff", 1, "Inside ability range, outside its melee.")
    cfgSlider(standing.content, "Melee standoff", "studs", 15, 50, false, "mobStandoff", 2, "From a melee mob, past its body: outside its swing whatever happens. The measured ability range less the margin wins when it is further.")
    cfgSlider(standing.content, "Ranged standoff", "studs", 10, 50, false, "rangedStandoff", 2.5, "From a ranged mob, past its body. It shoots either way; this only keeps a little room to dodge.")
    cfgToggle(standing.content, "Strafe at standoff", "strafe", 4, "Circle the target instead of standing still.")
    cfgSlider(standing.content, "Strafe speed", "of walk", 0.2, 1.0, true, "strafeSpeedFraction", 5, "Fraction of the walking speed used while circling.")
    local moving = K.section(body, "Moving", 4, "Walking and the escape burst.")
    cfgSlider(moving.content, "Walk", "studs/s", 12, 30, false, "tweenWalk", 1, "Speed assumed when planning a walk. The character walks at its own WalkSpeed; only the escape burst changes it.")
    cfgSlider(moving.content, "Escape", "studs/s", 12, 34, false, "tweenEscape", 2, "Speed while leaving danger.")
    cfgSlider(moving.content, "Slam sprint", "studs/s", 20, 34, false, "tweenSlam", 2.1, "Speed during the Champion's jump slam only: two seconds to leave a 67 stud cube. If the anti-cheat ever kicks right after a slam, this is the first dial to turn down.")
    cfgSlider(moving.content, "Burst length", "s", 1, 6, true, "boostUrgentRun", 2.2, "How long a speed burst may hold while something is coming, before it rests half a second. Longer is faster and more visible.")

    -- Dodge
    local d = dodge.body
    cfgToggle(d, "Blink out of hitboxes", "blink", 0, "A hop of a few studs when a lethal box covers you and fires before you could walk out. Only onto floor at the same height.")
    cfgToggle(d, "Blink against mobs too", "blinkMobs", 0.5, "Also hop out of mob attacks, such as a wall of mage shots that closes every gap. Kept to one hop at a time, nine seconds apart and twice a minute, because the anti-cheat kicks for repeated pairs.")
    cfgSlider(d, "Blink distance", "studs", 4, 14, false, "blinkMax", 0, "At most this far; the nearest clear spot wins.")
    K.caption(d, "Every attack becomes a box with a live window. A ring of spots round you is scored at the moments each would be reached; danger already on you is discounted only until the ground under you fires.", 1)
    cfgSlider(d, "Body margin", "studs", 0.5, 6, true, "dodgeMargin", 1.2, "Clearance kept round the character: a box counts as hit this far outside its edge (the inner white outline). Hits landed 1.5-3.3 studs outside their boxes.")
    cfgSlider(d, "Shoulder", "studs", 0, 6, true, "dodgeShoulder", 1.4, "Soft band past the margin where a spot costs a little (the outer white outline). 0 = hard edge.")
    cfgSlider(d, "Wall padding", "studs", 0, 12, false, "wallPadding", 1.6, "A spot with a wall closer than this is orange: not recommended, taken only when no open clean spot exists. A wall in the way is red: never.")
    cfgSlider(d, "Arena radius", "studs", 50, 140, false, "arenaRadius", 1.9, "How far the first boss's floor reaches from the middle of his arena. Spots past it cost, and spots more than fifteen studs past it are never taken.")
    cfgSlider(d, "Reach", "studs", 8, 30, false, "dodgeReach", 2, "Radius of the ring of spots.")
    cfgSlider(d, "Rings", "", 2, 8, false, "dodgeRings", 2.1, "How many rings of spots out to the reach; more rings, smaller gaps between them.")
    cfgSlider(d, "Spots per ring", "", 8, 32, false, "dodgeRays", 2.2, "Spots round each ring; every other ring is turned half a step so the spots interleave.")
    cfgSlider(d, "Lead", "s", 0.3, 2.0, true, "dodgeLead", 3, "A standing telegraph counts as live this long before it fires.")
    cfgSlider(d, "Dwell", "s", 0.2, 1.5, true, "dodgeDwell", 5, "A spot must stay clear this long after arrival.")
    cfgSlider(d, "Move at", "danger", 0.05, 0.6, true, "dodgeMoveAt", 6, "Danger here at or above this: relocate.")
    cfgSlider(d, "Strafe bias", "", 0, 0.5, true, "dodgeStrafeWeight", 8, "Preference for moving across the target's line rather than along it.")
    cfgSlider(d, "Default fire", "s", 0.3, 3.0, true, "defaultFire", 9, "A telegraphed attack with no seed is assumed to fire this long after it appears.")
    cfgSlider(d, "Default live", "s", 0.2, 3.0, true, "defaultLive", 10, "And to hurt for this long.")

    -- Queue
    local q = K.section(queue.body, "Queue", 1, "Queue the next run from the lobby, and replay a finished one.")
    K.caption(q.content, "In the lobby a party for the map and difficulty below is created and started through the game's own lobby remotes. In a run, when the dungeon ends and you own the party, the same replay the Replay button sends goes out.", 1)
    cfgToggle(q.content, "Auto queue", "autoQueue", 2, "Queue and replay on their own.", function() S.LB.arrivedAt, S.LB.lastAttempt = nil, -math.huge end)
    cfgToggle(q.content, "Press START in the dungeon", "autoStartDungeon", 2.4, "A queued run waits at the spawn until START is pressed; the script presses it.")
    cfgToggle(q.content, "Autofarm off in lobby, on in dungeon", "autoFarmByPlace", 2.5, "The master switch follows the place, once per place change.", function() S.LB.farmAppliedFor = nil end)
    local mapOptions, diffOptions = {}, {}
    for i, name in ipairs(S.QUEUE_MAPS) do mapOptions[i] = { value = name, label = name } end
    for i, name in ipairs(S.QUEUE_DIFFICULTIES) do diffOptions[i] = { value = name, label = name } end
    track(K.dropdown(q.content, "Map", mapOptions, function() return CFG.autoQueueMap end, function(v) CFG.autoQueueMap = v end, 3, "The dungeon to queue, by the name on its lobby tile."))
    track(K.dropdown(q.content, "Difficulty", diffOptions, function() return CFG.autoQueueDifficulty end, function(v) CFG.autoQueueDifficulty = v end, 4, "The difficulty tile."))
    cfgToggle(q.content, "Hardcore", "autoQueueHardcore", 5, "One life for everyone in the party.")
    cfgToggle(q.content, "Private party", "autoQueuePrivate", 6, "Nobody joins uninvited.")
    cfgSlider(q.content, "Lobby delay", "s", 2, 30, false, "autoQueueDelay", 7, "Seconds in the lobby before queueing.")
    cfgToggle(q.content, "Stay for the bonus boss", "bonusBoss", 7.5, "After the last boss the game asks whether to stay and fight the bonus boss. Off answers no; its attacks are not mapped yet.")
    cfgToggle(q.content, "Replay when a run ends", "autoQueueReplay", 8, "As the party owner, send the game's own replay when the run ends.")
    local queueLabel = K.label(q.content, "", "captionSub", 10)
    queueLabel.Size = UDim2.new(1, 0, 0, 22)
    S.refreshQueuePanel = function() if queueLabel.Parent then queueLabel.Text = "Queue: " .. tostring(S.LB.status) end end
    S.refreshQueuePanel()
    local qb = K.buttonRow(q.content, 11)
    qb.add("Queue now", "accent", function() S.queueNow("button") end)
    qb.add("Replay now", "accent", function() S.replayNow() end)
    q.setOpen(true)

    -- Overlays
    local o = overlays.body
    cfgToggle(o, "Draw attacks", "drawHazards", 1, "One translucent box per attack, coloured by stage.", function(v) if not v then clearDrawing() end end)
    cfgToggle(o, "Draw the spot", "drawTarget", 2, "The spot the field is heading for.")
    cfgToggle(o, "Draw path nodes", "drawPath", 2.3, "The travel waypoints (blue; the one being walked to is bright).")
    cfgToggle(o, "Draw spot candidates", "drawSpots", 2.6, "Every spot the field scored this frame: green clean, orange a wall inside the padding, yellow warm, red hot. Grey is not danger: a wall in the way, or no floor there.")
    cfgToggle(o, "Draw ability range", "drawAbility", 2.8, "A ring of dots at the measured ability range round you.")
    cfgToggle(o, "Draw projected AoE", "drawAoe", 2.82, "The shape and size of the next cast, drawn where it would land. It appears once a cast has been seen, since the size is measured from the ability itself.")
    cfgSlider(o, "Marker size", "x", 0.3, 2.0, true, "markerScale", 2.9, "Scales every dot drawn on the ground: the spot candidates, the blue path nodes and the ability ring.")
    cfgToggle(o, "Show hitbox parts", "showHitboxes", 2.82, "The game's own invisible hitBox parts, made visible in pink: every attack Model in the workspace, tracked or not (the parked beams at the Champion's hub included). Restored when off.")
    cfgToggle(o, "Label hazards", "labelHazards", 2.85, "The name of every tracked attack over its box, with live or the seconds until it fires.")
    cfgToggle(o, "Label unknown spawns", "labelUnknown", 2.9, "Anything that appears within 80 studs that the reader did not recognise, named in grey with a ? for ten seconds. Read the name off and it can be added to the catalogue.")
    cfgSlider(o, "Box transparency", "", 0.3, 0.95, true, "hazardTransparency", 3, "How see-through the attack boxes are.")
    for i, row in ipairs({ { "Safe to cross", "colorFloor", "Not firing for a while yet." }, { "About to fire", "colorSoon", "Inside the lead." }, { "Live", "colorLive", "Hurts now." } }) do
        track(K.colorRow(o, row[1], function() return CFG[row[2]] end, function(c) CFG[row[2]] = c end, 3 + i, row[3]))
    end

    -- Streamer mode
    local sm = K.section(o, "Streamer mode", 8, "Nothing on screen says who is playing. Each part is its own toggle; everything goes back to normal when the mode is off.")
    local function stAfter() S.streamerRefresh() end
    cfgToggle(sm.content, "Streamer mode", "streamer", 1, "The master switch: hides what is ticked below, puts it all back when off.", stAfter)
    cfgToggle(sm.content, "Hide my name", "streamerName", 2, "Your name, title and VIP tag over your head, and the name on the HUD.", stAfter)
    cfgToggle(sm.content, "Hide my health", "streamerHealth", 3, "The health numbers over your head and the HUD's health bar.", stAfter)
    cfgToggle(sm.content, "Black block for the body", "streamerBody", 4, "The character is drawn as a black block the size of the field's spot marker; the model and its armour are invisible.", stAfter)
    cfgToggle(sm.content, "Hide my level and portrait", "streamerLevel", 4.5, "The level chip over your head and on the HUD, and your avatar portrait. A level and a VIP tag together name an account almost as well as the name does.", stAfter)
    cfgToggle(sm.content, "Hide gold, gems and XP", "streamerWealth", 4.6, "The currency row and the experience bar on the HUD.", stAfter)
    cfgToggle(sm.content, "Hide other players' names", "streamerOthers", 5, "Their nameplates: name, title and VIP tag.", stAfter)
    cfgToggle(sm.content, "Hide the player lists", "streamerLeaderboard", 6, "The game's player list and Roblox's.", stAfter)
    cfgToggle(sm.content, "Hide the chat", "streamerChat", 7, "Roblox's chat window.", stAfter)
    sm.setOpen(true)

    -- Low detail
    local ld = K.section(o, "Low detail", 9, "The map stripped to plain shapes: easier to read, and a good deal faster. Nothing is deleted and nothing you can walk into changes, so the bot plays exactly the same.")
    local function ldAfter() S.lowDetailRefresh() end
    cfgToggle(ld.content, "Low detail", "lowDetail", 1, "The master switch: applies what is ticked below, puts it all back when off.", ldAfter)
    cfgToggle(ld.content, "Flat surfaces", "lowTextures", 2, "Every surface plain and matt, mesh textures and decals off.", ldAfter)
    cfgToggle(ld.content, "No particles or beams", "lowEffects", 3, "Particle emitters, trails, beams, fire and smoke switched off.", ldAfter)
    cfgToggle(ld.content, "Flat lighting", "lowLighting", 4, "No shadows, fog, atmosphere or camera effects, and still water.", ldAfter)
    cfgToggle(ld.content, "Hide scenery", "lowDecorations", 5, "Anything you cannot walk into is made invisible: snow, foliage and ornament.", ldAfter)
    cfgToggle(ld.content, "Delete scenery instead", "lowDeleteMeshes", 5.5, "Faster still: that same scenery, and this map's named decoration, is removed rather than hidden. Only ever what you cannot walk into, so the floor, the walls and the stairs stay. What is deleted cannot come back when the mode goes off; rejoin for that.", ldAfter)
    cfgToggle(ld.content, "Strip the attacks too", "lowAttackEffects", 6, "Off by default. Attacks, telegraphs and boss mechanics are never hidden or flattened whatever this is set to; on, they lose their loose particles as well.", ldAfter)
    ld.setOpen(false)

    -- Configs
    local cb = configs.body
    K.caption(cb, ("Version %s. Settings save on their own whenever they change, when a teleport begins, and when the script is closed."):format(SCRIPT_VERSION), 1)
    local row = K.buttonRow(cb, 2)
    row.add("Save now", "accent", function() saveConfig() end)
    row.add("Reload", "accent", function() loadConfig() refreshAll() end)
    cfgToggle(cb, "Debug prints", "debugPrints", 3, "Log what the script decides to the console.")
    K.button(cb, "Close the script", "danger", destructScript, 4, "Remove everything this script made and stop.")

    -- open/close
    local dim = Instance.new("Frame")
    dim.Name, dim.BackgroundColor3, dim.BackgroundTransparency, dim.BorderSizePixel, dim.Size, dim.Visible, dim.ZIndex = "Dim", Color3.new(0, 0, 0), 0.5, 0, UDim2.fromScale(1, 1), false, 1
    dim.Parent = gui
    applyVisibility = function()
        for _, w in pairs(windows) do w.frame.Visible = guiOpen or w.isPinned() end
        dim.Visible = guiOpen
        if not guiOpen then K.hideTip() end
    end
    sliderConnections[#sliderConnections + 1] = UserInputService.InputBegan:Connect(function(input, processed)
        if not processed and input.KeyCode.Name == CFG.menuKey then guiOpen = not guiOpen applyVisibility() end
    end)
    applyVisibility()

    -- HUD, bottom-left: title chip (name | build | fps), a Playtime / Status / Ping card, the hint and the Autofarm pill.
    local hud = Instance.new("Frame")
    hud.Name, hud.BackgroundTransparency, hud.AnchorPoint, hud.Position, hud.Size, hud.ZIndex = "HUD", 1, Vector2.new(0, 1), UDim2.new(0, 20, 1, -20), UDim2.fromOffset(360, 173), 2
    hud.Parent = gui
    local function panel(name, y, w, h, radius)
        local p = Instance.new("Frame")
        p.Name, p.BackgroundColor3, p.BorderSizePixel, p.Position, p.Size, p.ZIndex = name, Color3.new(1, 1, 1), 0, UDim2.fromOffset(0, y), UDim2.fromOffset(w, h), 3
        p.Parent = hud
        K.corner(p, radius) K.stroke(p, T.Hairline, 1) K.bodyGradient(p) K.shadow(p, 6, 2.0, 8, 0.065, radius)
        local bar = Instance.new("Frame")   -- the accent pill, inset so nothing square shows past the corners
        bar.Name, bar.BackgroundColor3, bar.BorderSizePixel, bar.Position, bar.Size, bar.ZIndex = "AccentBar", Color3.new(1, 1, 1), 0, UDim2.fromOffset(4, 0), UDim2.new(1, -8, 0, 3), 5
        bar.Parent = p
        K.corner(bar, 2) K.accentGradient(bar, 0)
        return p
    end
    local function text(parent, str, style, x, y, w, h, colour, right)
        local l = K.label(parent, str, style, 1)
        l.Position, l.Size, l.TextTruncate, l.ZIndex = UDim2.fromOffset(x, y), UDim2.fromOffset(w, h), Enum.TextTruncate.AtEnd, 4
        if colour then l.TextColor3 = colour end
        if right then l.TextXAlignment = Enum.TextXAlignment.Right end
        return l
    end
    local chip = panel("TitleChip", 0, 326, 34, T.RadiusMd)
    text(chip, "dqr pathfinding", "windowChip", 12, 7, 138, 20)
    text(chip, "|", "captionKey", 154, 7, 6, 20, T.TextMuted)
    text(chip, SCRIPT_VERSION, "rowStat", 168, 7, 70, 20, T.TextSub)
    text(chip, "|", "captionKey", 240, 7, 6, 20, T.TextMuted)
    local fpsLabel = text(chip, "fps: --", "monoStat", 254, 7, 66, 20)
    local stats = panel("Stats", 42, 360, 95, T.RadiusLg)
    local function statRow(name, y) text(stats, name, "rowStat", 14, y, 120, 24) return text(stats, "--", "monoStat", 140, y, 206, 24, nil, true) end
    local playtimeValue, statusValue, pingValue = statRow("Playtime", 11), statRow("Status", 37), statRow("Ping", 63)
    local hint = K.label(hud, "[" .. CFG.menuKey .. "] to open GUI", "rowLabel", 1)
    hint.Position, hint.Size, hint.TextColor3, hint.TextStrokeTransparency, hint.ZIndex = UDim2.fromOffset(0, 147), UDim2.fromOffset(200, 24), T.TextSub, 0.1, 3
    local status = Instance.new("Frame")
    status.Name, status.BackgroundColor3, status.BorderSizePixel, status.Position, status.Size, status.ZIndex = "StatusChip", T.SurfaceChip, 0, UDim2.fromOffset(210, 147), UDim2.fromOffset(150, 24), 3
    status.Parent = hud
    K.corner(status, T.RadiusMd) K.stroke(status, T.Hairline, 1)
    local dot = Instance.new("Frame")
    dot.Name, dot.BackgroundColor3, dot.BorderSizePixel, dot.AnchorPoint, dot.Position, dot.Size, dot.ZIndex = "Dot", T.StatusBad, 0, Vector2.new(0, 0.5), UDim2.new(0, 9, 0.5, 0), UDim2.fromOffset(6, 6), 4
    dot.Parent = status
    K.corner(dot, 3)
    local statusKey = K.label(status, "Autofarm:", "captionKey", 1)
    statusKey.Position, statusKey.Size, statusKey.ZIndex = UDim2.fromOffset(21, 0), UDim2.new(1, -21, 1, 0), 4
    local statusPill = K.label(status, "Disabled", "captionStat", 2)
    statusPill.Position, statusPill.Size, statusPill.TextColor3, statusPill.ZIndex = UDim2.fromOffset(76, 0), UDim2.new(1, -85, 1, 0), T.StatusBad, 4

    local Stats = game:GetService("Stats")
    local frames, elapsed = 0, 0
    RT.hudPlayStart = RT.hudPlayStart or os.clock()
    RT.hudConnection = RunService.Heartbeat:Connect(function(dt)
        if RT.destroyed then return end
        frames, elapsed = frames + 1, elapsed + dt
        if elapsed < 0.25 then return end
        fpsLabel.Text = ("fps: %d"):format(math.floor(frames / elapsed + 0.5))
        frames, elapsed = 0, 0
        local seconds = os.clock() - RT.hudPlayStart
        playtimeValue.Text = ("%02d:%02d"):format(math.floor(seconds / 60), math.floor(seconds % 60))
        if RT.lastErrorAt and os.clock() - RT.lastErrorAt < 6 then
            statusValue.Text = "ERROR " .. tostring(RT.lastError)   -- a stage that threw: on screen, not only in the console
        else
            local tracked = 0
            for _ in pairs(RD.models) do tracked = tracked + 1 end
            local spots = CFG.drawSpots and #(S.DG.cands or {}) or -1   -- -1 means the overlay is switched off, not empty
            statusValue.Text = ("%s  [%d attacks, %s]"):format(tostring(RT.movementState), tracked,
                spots < 0 and "spots off" or ("%d spots"):format(spots))
        end
        local parts = {}
        for slot, s in pairs(RD.abilitySlots or {}) do
            parts[#parts + 1] = ("%s %s: %s%s"):format(string.upper(slot), s.name or "?", s.cap and (s.cap .. " studs") or (s.reach and ("at least " .. s.reach) or "?"),
                s.aoeX and (", AoE " .. math.floor(s.aoeX + 0.5) .. (s.aoeRound and " round" or (" x " .. math.floor(s.aoeZ + 0.5)))) or "")
        end
        table.sort(parts)
        rangeCaption.Text = #parts > 0 and ("Measured - " .. table.concat(parts, "; ") .. ". The least ranged one sets the fight distance.") or "Ability range: not measured yet (cast at a target)"
        local ping = 0
        pcall(function() ping = Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
        pingValue.Text = ("%d"):format(math.floor(ping + 0.5))
        local running = RT.farmEnabled and not RT.destroyed
        local str, colour = running and "Running" or "Disabled", running and T.StatusGood or T.StatusBad
        if statusPill.Text ~= str then statusPill.Text, statusPill.TextColor3, dot.BackgroundColor3 = str, colour, colour end
    end)
end

S.destructScript, S.refreshAllWidgets = destructScript, refreshAll
S.setLoopButtonState = function() if UI.masterRender then pcall(UI.masterRender) end end

-- startup
print(("DUNGEON AUTOFARM %s \"%s\"  |  build %s"):format(SCRIPT_VERSION, S.SCRIPT_CODENAME, S.SCRIPT_BUILD_DATE))
loadConfig()
buildUI()
S.readerStart()
S.setState("ready")
-- Each stage runs under its own pcall, so one failing stage never stops the others; a failure is always warned
-- (throttled), not only with debug prints, because a silent per-frame error looks like the bot freezing.
local lastWarn = {}
local function stage(name, fn, t0)
    local ok, err = pcall(fn, t0)
    if ok then return end
    if name == "brain" then releaseCharacter() end   -- a walk already commanded would otherwise carry on in that direction
    RT.lastError, RT.lastErrorAt = ("%s: %s"):format(name, tostring(err)), os.clock()   -- and on the HUD, where it cannot be missed
    -- Every one of them is kept for the recording, counted by stage and message, so a fault that only shows for a
    -- moment on screen still reaches the file (Chris: include these errors in the recording).
    RT.errorLog = RT.errorLog or {}
    local key = ("%s: %s"):format(name, tostring(err))
    local e = RT.errorLog[key]
    if e then e.n, e.last = e.n + 1, os.clock()
    else RT.errorLog[key] = { n = 1, first = os.clock(), last = os.clock() } end
    if os.clock() - (lastWarn[name] or -math.huge) > 5 then
        lastWarn[name] = os.clock()
        warn(("[DQ %s] %s: %s"):format(SCRIPT_VERSION, name, tostring(err)))
    end
end
local function farmStage(t0) if RT.farmEnabled then S.brainTick(t0) else releaseCharacter() S.setState("off") end end
RT.streamerConnection = RunService.Heartbeat:Connect(function()
    if RT.destroyed then return end
    pcall(streamerTick, os.clock())
    pcall(lowDetailTick)
end)
RT.mainConnection = RunService.Heartbeat:Connect(function()
    if RT.destroyed then return end
    local t0 = os.clock()
    stage("reader", S.readerTick, t0)
    stage("lobby", S.lobbyTick, t0)
    stage("config", S.autosaveTick, t0)
    stage("brain", farmStage, t0)
    stage("draw", S.drawTick, t0)
    RT.tickMs = RT.tickMs * 0.9 + (os.clock() - t0) * 100
end)
end
    end)()
    module(S)
end
